/** static void CreateCityZoomTextSprites(void) */
export function CreateCityZoomTextSprites(): any {
  let i: any = null;
      let y: any = null;
      let sprite: any = null;
      let state: any = GetSubstructPtr(POKENAV_SUBSTRUCT_REGION_MAP_ZOOM);

       
      if (!IsRegionMapZoomed())
          y = 228;
      else
          y = 132;

      for (i = 0; i < ARRAY_COUNT(state.cityZoomTextSprites); i++)
      {
          let spriteId: any = CreateSprite(sCityZoomTextSpriteTemplate, 152 + i * 32, y, 8);
          sprite =gSprites[spriteId];
          sprite.data[0] = 0;
          sprite.data[1] = i * 4;
          sprite.data[2] = sprite.oam.tileNum;
          sprite.data[3] = 150;
          sprite.data[4] = i * 4;
          sprite.oam.tileNum += i * 4;
          state.cityZoomTextSprites[i] = sprite;
      }
}

/** static void SpriteCB_CityZoomText(struct Sprite *sprite) */
export function SpriteCB_CityZoomText(sprite: any): any {
  if (sprite.data[3])
      {
          sprite.data[3]--;
          return;
      }

      if (++sprite.data[0] > 11)
          sprite.data[0] = 0;

      if (++sprite.data[1] > 60)
          sprite.data[1] = 0;

      sprite.oam.tileNum = sprite.data[2] + sprite.data[1];
      if (sprite.data[5] < 4)
      {
          if (sprite.data[0] == 0)
          {
              sprite.data[5]++;
              sprite.data[3] = 120;
          }
      }
      else
      {
          if (sprite.data[1] == sprite.data[4])
          {
              sprite.data[5] = 0;
              sprite.data[0] = 0;
              sprite.data[3] = 120;
          }
      }
}

